1	package org.jsoup.safety;
2	
3	/*
4	    Thank you to Ryan Grove (wonko.com) for the Ruby HTML cleaner http://github.com/rgrove/sanitize/, which inspired
5	    this safe-list configuration, and the initial defaults.
6	 */
7	
8	import org.jsoup.helper.Validate;
9	import org.jsoup.internal.Normalizer;
10	import org.jsoup.internal.StringUtil;
11	import org.jsoup.nodes.Attribute;
12	import org.jsoup.nodes.Attributes;
13	import org.jsoup.nodes.Element;
14	
15	import java.util.HashMap;
16	import java.util.HashSet;
17	import java.util.Iterator;
18	import java.util.Map;
19	import java.util.Objects;
20	import java.util.Set;
21	
22	import static org.jsoup.internal.Normalizer.lowerCase;
23	
24	
25	/**
26	 Safelists define what HTML (elements and attributes) to allow through a {@link Cleaner}. Everything else is removed.
27	 <p>
28	 Start with one of the defaults:
29	 </p>
30	 <ul>
31	 <li>{@link #none}
32	 <li>{@link #simpleText}
33	 <li>{@link #basic}
34	 <li>{@link #basicWithImages}
35	 <li>{@link #relaxed}
36	 </ul>
37	 <p>
38	 If you need to allow more through (please be careful!), tweak a base safelist with:
39	 </p>
40	 <ul>
41	 <li>{@link #addTags(String... tagNames)}
42	 <li>{@link #addAttributes(String tagName, String... attributes)}
43	 <li>{@link #addEnforcedAttribute(String tagName, String attribute, String value)}
44	 <li>{@link #addProtocols(String tagName, String attribute, String... protocols)}
45	 </ul>
46	 <p>
47	 You can remove any setting from an existing safelist with:
48	 </p>
49	 <ul>
50	 <li>{@link #removeTags(String... tagNames)}
51	 <li>{@link #removeAttributes(String tagName, String... attributes)}
52	 <li>{@link #removeEnforcedAttribute(String tagName, String attribute)}
53	 <li>{@link #removeProtocols(String tagName, String attribute, String... removeProtocols)}
54	 </ul>
55	
56	 <p>
57	 The {@link Cleaner} and these safelists assume that you want to clean a <code>body</code> fragment of HTML (to add user
58	 supplied HTML into a templated page), and not to clean a full HTML document. If the latter is the case, you could wrap
59	 the templated document HTML around the cleaned body HTML.
60	 </p>
61	 <p>
62	 Safelists are mutable. A {@link Cleaner} uses the supplied safelist directly, so later changes affect later cleaning
63	 calls. If you want to share a safelist across threads, finish configuring it first and do not mutate it while it is in
64	 use. To build a variant from an existing configuration, use {@link #Safelist(Safelist)} to make a copy.
65	 </p>
66	 <p>
67	 If you are going to extend a safelist, please be very careful. Make sure you understand what attributes may lead to
68	 XSS attack vectors. URL attributes are particularly vulnerable and require careful validation. See 
69	 the <a href="https://owasp.org/www-community/xss-filter-evasion-cheatsheet">XSS Filter Evasion Cheat Sheet</a> for some
70	 XSS attack examples (that jsoup will safeguard against with the default Cleaner and Safelist configuration).
71	 </p>
72	 */
73	public class Safelist {
74	    private static final String All = ":all";
75	    private static final TagName AllTag = TagName.valueOf(All);
76	    private static final String Srcset = "srcset";
77	    private static final AttributeKey SrcsetKey = AttributeKey.valueOf(Srcset);
78	    private final Set<TagName> tagNames; // tags allowed, lower case. e.g. [p, br, span]
79	    private final Map<TagName, Set<AttributeKey>> attributes; // tag -> attribute[]. allowed attributes [href] for a tag.
80	    private final Map<TagName, Map<AttributeKey, AttributeValue>> enforcedAttributes; // always set these attribute values
81	    private final Map<TagName, Map<AttributeKey, Set<Protocol>>> protocols; // allowed URL protocols for attributes
82	    private boolean preserveRelativeLinks; // option to preserve relative links
83	
84	    /**
85	     This safelist allows only text nodes: any HTML Element or any Node other than a TextNode will be removed.
86	     <p>
87	     Note that the output of {@link org.jsoup.Jsoup#clean(String, Safelist)} is still <b>HTML</b> even when using
88	     this Safelist, and so any HTML entities in the output will be appropriately escaped. If you want plain text, not
89	     HTML, you should use a text method such as {@link Element#text()} instead, after cleaning the document.
90	     </p>
91	     <p>Example:</p>
92	     <pre>{@code
93	     String sourceBodyHtml = "<p>5 is &lt; 6.</p>";
94	     String html = Jsoup.clean(sourceBodyHtml, Safelist.none());
95	
96	     Cleaner cleaner = new Cleaner(Safelist.none());
97	     String text = cleaner.clean(Jsoup.parse(sourceBodyHtml)).text();
98	
99	     // html is: 5 is &lt; 6.
100	     // text is: 5 is < 6.
101	     }</pre>
102	
103	     @return safelist
104	     */
105	    public static Safelist none() {
106	        return new Safelist();
107	    }
108	
109	    /**
110	     This safelist allows only simple text formatting: <code>b, em, i, strong, u</code>. All other HTML (tags and
111	     attributes) will be removed.
112	
113	     @return safelist
114	     */
115	    public static Safelist simpleText() {
116	        return new Safelist()
117	                .addTags("b", "em", "i", "strong", "u")
118	                ;
119	    }
120	
121	    /**
122	     <p>
123	     This safelist allows a fuller range of text nodes: <code>a, b, blockquote, br, cite, code, dd, dl, dt, em, i, li,
124	     ol, p, pre, q, small, span, strike, strong, sub, sup, u, ul</code>, and appropriate attributes.
125	     </p>
126	     <p>
127	     Links (<code>a</code> elements) can point to <code>http, https, ftp, mailto</code>, and have an enforced
128	     <code>rel=nofollow</code> attribute if they link offsite (as indicated by the specified base URI).
129	     </p>
130	     <p>
131	     Does not allow images.
132	     </p>
133	
134	     @return safelist
135	     */
136	    public static Safelist basic() {
137	        return new Safelist()
138	                .addTags(
139	                        "a", "b", "blockquote", "br", "cite", "code", "dd", "dl", "dt", "em",
140	                        "i", "li", "ol", "p", "pre", "q", "small", "span", "strike", "strong", "sub",
141	                        "sup", "u", "ul")
142	
143	                .addAttributes("a", "href")
144	                .addAttributes("blockquote", "cite")
145	                .addAttributes("q", "cite")
146	
147	                .addProtocols("a", "href", "ftp", "http", "https", "mailto")
148	                .addProtocols("blockquote", "cite", "http", "https")
149	                .addProtocols("cite", "cite", "http", "https")
150	
151	                .addEnforcedAttribute("a", "rel", "nofollow") // has special handling for external links, in Cleaner
152	                ;
153	
154	    }
155	
156	    /**
157	     This safelist allows the same text tags as {@link #basic}, and also allows <code>img</code> tags, with appropriate
158	     attributes, with <code>src</code> pointing to <code>http</code> or <code>https</code>.
159	
160	     @return safelist
161	     */
162	    public static Safelist basicWithImages() {
163	        return basic()
164	                .addTags("img")
165	                .addAttributes("img", "align", "alt", "height", "src", "title", "width")
166	                .addProtocols("img", "src", "http", "https")
167	                ;
168	    }
169	
170	    /**
171	     This safelist allows a full range of text and structural body HTML: <code>a, b, blockquote, br, caption, cite,
172	     code, col, colgroup, dd, div, dl, dt, em, h1, h2, h3, h4, h5, h6, i, img, li, ol, p, pre, q, small, span, strike, strong, sub,
173	     sup, table, tbody, td, tfoot, th, thead, tr, u, ul</code>
174	     <p>
175	     Links do not have an enforced <code>rel=nofollow</code> attribute, but you can add that if desired.
176	     </p>
177	
178	     @return safelist
179	     */
180	    public static Safelist relaxed() {
181	        return new Safelist()
182	                .addTags(
183	                        "a", "b", "blockquote", "br", "caption", "cite", "code", "col",
184	                        "colgroup", "dd", "div", "dl", "dt", "em", "h1", "h2", "h3", "h4", "h5", "h6",
185	                        "i", "img", "li", "ol", "p", "pre", "q", "small", "span", "strike", "strong",
186	                        "sub", "sup", "table", "tbody", "td", "tfoot", "th", "thead", "tr", "u",
187	                        "ul")
188	
189	                .addAttributes("a", "href", "title")
190	                .addAttributes("blockquote", "cite")
191	                .addAttributes("col", "span", "width")
192	                .addAttributes("colgroup", "span", "width")
193	                .addAttributes("img", "align", "alt", "height", "src", "title", "width")
194	                .addAttributes("ol", "start", "type")
195	                .addAttributes("q", "cite")
196	                .addAttributes("table", "summary", "width")
197	                .addAttributes("td", "abbr", "axis", "colspan", "rowspan", "width")
198	                .addAttributes(
199	                        "th", "abbr", "axis", "colspan", "rowspan", "scope",
200	                        "width")
201	                .addAttributes("ul", "type")
202	
203	                .addProtocols("a", "href", "ftp", "http", "https", "mailto")
204	                .addProtocols("blockquote", "cite", "http", "https")
205	                .addProtocols("cite", "cite", "http", "https")
206	                .addProtocols("img", "src", "http", "https")
207	                .addProtocols("q", "cite", "http", "https")
208	                ;
209	    }
210	
211	    /**
212	     Create a new, empty safelist. Generally it will be better to start with a default prepared safelist instead.
213	
214	     @see #basic()
215	     @see #basicWithImages()
216	     @see #simpleText()
217	     @see #relaxed()
218	     */
219	    public Safelist() {
220	        tagNames = new HashSet<>();
221	        attributes = new HashMap<>();
222	        enforcedAttributes = new HashMap<>();
223	        protocols = new HashMap<>();
224	        preserveRelativeLinks = false;
225	    }
226	
227	    /**
228	     Deep copy an existing Safelist to a new Safelist.
229	     @param copy the Safelist to copy
230	     */
231	    public Safelist(Safelist copy) {
232	        this();
233	        tagNames.addAll(copy.tagNames);
234	        for (Map.Entry<TagName, Set<AttributeKey>> copyTagAttributes : copy.attributes.entrySet()) {
235	            attributes.put(copyTagAttributes.getKey(), new HashSet<>(copyTagAttributes.getValue()));
236	        }
237	        for (Map.Entry<TagName, Map<AttributeKey, AttributeValue>> enforcedEntry : copy.enforcedAttributes.entrySet()) {
238	            enforcedAttributes.put(enforcedEntry.getKey(), new HashMap<>(enforcedEntry.getValue()));
239	        }
240	        for (Map.Entry<TagName, Map<AttributeKey, Set<Protocol>>> protocolsEntry : copy.protocols.entrySet()) {
241	            Map<AttributeKey, Set<Protocol>> attributeProtocolsCopy = new HashMap<>();
242	            for (Map.Entry<AttributeKey, Set<Protocol>> attributeProtocols : protocolsEntry.getValue().entrySet()) {
243	                attributeProtocolsCopy.put(attributeProtocols.getKey(), new HashSet<>(attributeProtocols.getValue()));
244	            }
245	            protocols.put(protocolsEntry.getKey(), attributeProtocolsCopy);
246	        }
247	        preserveRelativeLinks = copy.preserveRelativeLinks;
248	    }
249	
250	    /**
251	     Add a list of allowed elements to a safelist. (If a tag is not allowed, it will be removed from the HTML.)
252	
253	     @param tags tag names to allow
254	     @return this (for chaining)
255	     */
256	    public Safelist addTags(String... tags) {
257	        Validate.notNull(tags);
258	
259	        for (String tagName : tags) {
260	            Validate.notEmpty(tagName);
261	            Validate.isFalse(tagName.equalsIgnoreCase("noscript"),
262	                "noscript is unsupported in Safelists, due to incompatibilities between parsers with and without script-mode enabled");
263	            tagNames.add(TagName.valueOf(tagName));
264	        }
265	        return this;
266	    }
267	
268	    /**
269	     Remove a list of allowed elements from a safelist. (If a tag is not allowed, it will be removed from the HTML.)
270	
271	     @param tags tag names to disallow
272	     @return this (for chaining)
273	     */
274	    public Safelist removeTags(String... tags) {
275	        Validate.notNull(tags);
276	
277	        for(String tag: tags) {
278	            Validate.notEmpty(tag);
279	            TagName tagName = TagName.valueOf(tag);
280	
281	            if(tagNames.remove(tagName)) { // Only look in sub-maps if tag was allowed
282	                attributes.remove(tagName);
283	                enforcedAttributes.remove(tagName);
284	                protocols.remove(tagName);
285	            }
286	        }
287	        return this;
288	    }
289	
290	    /**
291	     Add a list of allowed attributes to a tag. (If an attribute is not allowed on an element, it will be removed.)
292	     <p>
293	     E.g.: <code>addAttributes("a", "href", "class")</code> allows <code>href</code> and <code>class</code> attributes
294	     on <code>a</code> tags.
295	     </p>
296	     <p>
297	     To make an attribute valid for <b>all tags</b>, use the pseudo tag <code>:all</code>, e.g.
298	     <code>addAttributes(":all", "class")</code>.
299	     </p>
300	
301	     @param tag  The tag the attributes are for. The tag will be added to the allowed tag list if necessary.
302	     @param attributes List of valid attributes for the tag
303	     @return this (for chaining)
304	     */
305	    public Safelist addAttributes(String tag, String... attributes) {
306	        Validate.notEmpty(tag);
307	        Validate.notNull(attributes);
308	        Validate.isTrue(attributes.length > 0, "No attribute names supplied.");
309	
310	        addTags(tag);
311	        TagName tagName = TagName.valueOf(tag);
312	        Set<AttributeKey> attributeSet = new HashSet<>();
313	        for (String key : attributes) {
314	            Validate.notEmpty(key);
315	            attributeSet.add(AttributeKey.valueOf(key));
316	        }
317	        Set<AttributeKey> currentSet = this.attributes.computeIfAbsent(tagName, k -> new HashSet<>());
318	        currentSet.addAll(attributeSet);
319	        return this;
320	    }
