322	    /**
323	     Remove a list of allowed attributes from a tag. (If an attribute is not allowed on an element, it will be removed.)
324	     <p>
325	     E.g.: <code>removeAttributes("a", "href", "class")</code> disallows <code>href</code> and <code>class</code>
326	     attributes on <code>a</code> tags.
327	     </p>
328	     <p>
329	     To make an attribute invalid for <b>all tags</b>, use the pseudo tag <code>:all</code>, e.g.
330	     <code>removeAttributes(":all", "class")</code>.
331	     </p>
332	
333	     @param tag  The tag the attributes are for.
334	     @param attributes List of invalid attributes for the tag
335	     @return this (for chaining)
336	     */
337	    public Safelist removeAttributes(String tag, String... attributes) {
338	        Validate.notEmpty(tag);
339	        Validate.notNull(attributes);
340	        Validate.isTrue(attributes.length > 0, "No attribute names supplied.");
341	
342	        TagName tagName = TagName.valueOf(tag);
343	        Set<AttributeKey> attributeSet = new HashSet<>();
344	        for (String key : attributes) {
345	            Validate.notEmpty(key);
346	            attributeSet.add(AttributeKey.valueOf(key));
347	        }
348	        if(tagNames.contains(tagName) && this.attributes.containsKey(tagName)) { // Only look in sub-maps if tag was allowed
349	            Set<AttributeKey> currentSet = this.attributes.get(tagName);
350	            currentSet.removeAll(attributeSet);
351	
352	            if(currentSet.isEmpty()) // Remove tag from attribute map if no attributes are allowed for tag
353	                this.attributes.remove(tagName);
354	        }
355	        if(tag.equals(All)) { // Attribute needs to be removed from all individually set tags
356	            Iterator<Map.Entry<TagName, Set<AttributeKey>>> it = this.attributes.entrySet().iterator();
357	            while (it.hasNext()) {
358	                Map.Entry<TagName, Set<AttributeKey>> entry = it.next();
359	                Set<AttributeKey> currentSet = entry.getValue();
360	                currentSet.removeAll(attributeSet);
361	                if(currentSet.isEmpty()) // Remove tag from attribute map if no attributes are allowed for tag
362	                    it.remove();
363	            }
364	        }
365	        return this;
366	    }
