387	        tagNames.add(tagName);
388	        AttributeKey attrKey = AttributeKey.valueOf(attribute);
389	        AttributeValue attrVal = AttributeValue.valueOf(value);
390	
391	        Map<AttributeKey, AttributeValue> attrMap = enforcedAttributes.computeIfAbsent(tagName, k -> new HashMap<>());
392	        attrMap.put(attrKey, attrVal);
