524	    /**
525	     * Test if the supplied attribute is allowed by this safelist for this tag.
526	     * <p>This method does not modify the input element or attribute.</p>
527	     * <p>Note that for {@code srcset} attributes, which hold a comma-separated list of URL candidates, this method
528	     * only tests that the attribute itself is allowed; the {@link Cleaner} validates each candidate URL against the
529	     * configured protocols when cleaning.</p>
530	     * @param tagName tag to consider allowing the attribute in
531	     * @param el element under test, to confirm protocol
532	     * @param attr attribute under test
533	     * @return true if allowed
534	     */
535	    public boolean isSafeAttribute(String tagName, Element el, Attribute attr) {
536	        TagName tag = TagName.valueOf(tagName);
537	        AttributeKey key = AttributeKey.valueOf(attr.getKey());
538	
539	        Set<AttributeKey> okSet = attributes.get(tag);
540	        if (okSet != null && okSet.contains(key)) {
541	            if (protocols.containsKey(tag)) {
542	                Map<AttributeKey, Set<Protocol>> attrProts = protocols.get(tag);
543	                // ok if not defined protocol; otherwise test. srcset URLs are tested per candidate in the Cleaner.
544	                return !attrProts.containsKey(key) || isSrcset(attr.getKey())
545	                    || isSafeProtocol(getProtocolValue(el, attr), attrProts.get(key));
546	            } else { // attribute found, no protocols defined, so OK
547	                return true;
548	            }
549	        }
550	        Map<AttributeKey, AttributeValue> enforcedSet = enforcedAttributes.get(tag);
551	        if (enforcedSet != null && enforcedSet.containsKey(key)) {
552	            // enforced attr key was LCed via AttributeKey.valueOf(attr.getKey()),
553	            // if the input already has that exact value, treat it as safe
554	            return enforcedSet.get(key).equals(AttributeValue.valueOf(attr.getValue()));
555	        }
556	        // no attributes defined for tag, try :all tag
557	        return !tagName.equals(All) && isSafeAttribute(All, el, attr);
558	    }
559	
560	    private String getProtocolValue(Element el, Attribute attr) {
561	        String value = el.absUrl(attr.getKey());
562	        if (value.isEmpty() && !StringUtil.hasHttpScheme(attr.getValue()))
563	            value = attr.getValue(); // if it could not be made abs, run as-is to allow custom unknown protocols
564	        return value;
565	    }
566	
567	    private boolean isSafeProtocol(String value, Set<Protocol> protocols) {
568	        for (Protocol protocol : protocols) {
569	            String prot = protocol.toString();
570	
571	            if (prot.equals("#")) { // allows anchor links
572	                if (isValidAnchor(value)) {
573	                    return true;
574	                } else {
575	                    continue;
576	                }
577	            }
578	
579	            String lc = lowerCase(value);
580	            if (lc.startsWith(prot)
581	                && lc.length() > prot.length()
582	                && lc.charAt(prot.length()) == ':') {
583	                return true;
584	            }
585	        }
586	        return false;
587	    }
