757	    /**
758	     Check if a URL attribute should be normalized to an absolute URL in the cleaned output. Uses the configured
759	     protocols for that tag+attribute pair, falling back to {@code :all} only if the tag does not define the
760	     attribute.
761	     */
762	    boolean shouldAbsUrl(String tagName, String attrKey) {
763	        if (preserveRelativeLinks) return false;
764	        return shouldAbsUrl(TagName.valueOf(tagName), AttributeKey.valueOf(attrKey));
765	    }
766	
767	    private boolean shouldAbsUrl(TagName tag, AttributeKey key) {
768	        Set<AttributeKey> allowedAttrs = attributes.get(tag);
769	        if (allowedAttrs != null && allowedAttrs.contains(key)) {
770	            Map<AttributeKey, Set<Protocol>> protocolsByAttr = protocols.get(tag);
771	            return protocolsByAttr != null && protocolsByAttr.containsKey(key);
772	        }
773	
774	        Map<AttributeKey, AttributeValue> enforcedAttrs = enforcedAttributes.get(tag);
775	        if (enforcedAttrs != null && enforcedAttrs.containsKey(key)) return false;
776	
777	        return !tag.equals(AllTag) && shouldAbsUrl(AllTag, key);
778	    }
