270	
271	        if (failure.get() != null)
272	            throw new AssertionError("Concurrent cleaner use failed", failure.get());
273	
274	        assertEquals(cleaned.length, next.get());
275	        for (String clean : cleaned) {
276	            assertEquals(expected, clean);
277	        }
